#!/usr/bin/env bash
set -euo pipefail
APP_BASE="$HOME/.local/share/pan-launcher"
APP_DIR="$APP_BASE/app"
VER_FILE="$APP_BASE/version.txt"
SERVER_PY="$APP_BASE/server.py"
PORT=41735
URL="http://127.0.0.1:$PORT/"
mkdir -p "$APP_BASE"

if ! command -v python3 >/dev/null 2>&1; then
  echo "Pan-launcher necesita python3 instalado en tu sistema." >&2
  exit 1
fi

TARGET_VER="1795718147255"
CUR_VER=""
[ -f "$VER_FILE" ] && CUR_VER="$(cat "$VER_FILE")"
if [ ! -f "$APP_DIR/index.html" ] || [ ! -f "$SERVER_PY" ] || [ "$CUR_VER" != "$TARGET_VER" ]; then
  rm -rf "$APP_DIR" && mkdir -p "$APP_DIR"
  PY_LINE=$(awk '/^__PAN_SERVER_PY_B64__$/{print NR + 1; exit 0;}' "$0")
  ZIP_LINE=$(awk '/^__PAN_ZIP_B64__$/{print NR + 1; exit 0;}' "$0")
  sed -n "${PY_LINE},$((ZIP_LINE - 2))p" "$0" | base64 --decode > "$SERVER_PY" 2>/dev/null || sed -n "${PY_LINE},$((ZIP_LINE - 2))p" "$0" | base64 -D > "$SERVER_PY"
  chmod +x "$SERVER_PY"
  tail -n+"$ZIP_LINE" "$0" | base64 --decode > "$APP_BASE/app.zip" 2>/dev/null || tail -n+"$ZIP_LINE" "$0" | base64 -D > "$APP_BASE/app.zip"
  python3 -m zipfile -e "$APP_BASE/app.zip" "$APP_DIR"
  cp -f "$0" "$APP_BASE/Pan-launcher.sh" 2>/dev/null || true
  chmod +x "$APP_BASE/Pan-launcher.sh" 2>/dev/null || true
  printf "%s" "$TARGET_VER" > "$VER_FILE"
  if [ -d "$HOME/.local/share/applications" ] || mkdir -p "$HOME/.local/share/applications" 2>/dev/null; then
    cat > "$HOME/.local/share/applications/pan-launcher.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=Pan Launcher
Comment=Minecraft Java Edition Optimizer & Launcher
Exec="$APP_BASE/Pan-launcher.sh"
Icon=$APP_DIR/assets/pan-logo.png
Terminal=false
Categories=Game;
EOF
  fi
  pkill -f "$SERVER_PY" >/dev/null 2>&1 || true
  sleep 0.2
fi

if ! curl -fsS "http://127.0.0.1:$PORT/api/health" 2>/dev/null | grep -q "canLaunchJava"; then
  pkill -f "$SERVER_PY" >/dev/null 2>&1 || true
  PAN_BASE_DIR="$APP_BASE" PAN_PORT="$PORT" nohup python3 "$SERVER_PY" >/dev/null 2>&1 &
  for _ in $(seq 1 25); do
    sleep 0.15
    if curl -fsS "http://127.0.0.1:$PORT/api/health" >/dev/null 2>&1; then break; fi
  done
fi

if [[ "$OSTYPE" == "darwin"* ]]; then
  if [ -d "/Applications/Google Chrome.app" ]; then
    open -a "Google Chrome" --args --app="$URL"
  elif [ -d "/Applications/Microsoft Edge.app" ]; then
    open -a "Microsoft Edge" --args --app="$URL"
  else
    open "$URL"
  fi
elif command -v google-chrome >/dev/null 2>&1; then
  google-chrome --app="$URL" >/dev/null 2>&1 &
elif command -v chromium >/dev/null 2>&1; then
  chromium --app="$URL" >/dev/null 2>&1 &
elif command -v chromium-browser >/dev/null 2>&1; then
  chromium-browser --app="$URL" >/dev/null 2>&1 &
else
  xdg-open "$URL" >/dev/null 2>&1 &
fi
exit 0
__PAN_SERVER_PY_B64__

__PAN_ZIP_B64__

